CREATE INDEX IF NOT EXISTS "kitchen_tickets_outlet_created_idx"
  ON "kitchen_tickets" USING btree ("outlet_id", "created_at");
--> statement-breakpoint

CREATE INDEX IF NOT EXISTS "kitchen_tickets_pending_call_idx"
  ON "kitchen_tickets" USING btree ("outlet_id") WHERE call_at is not null and call_ack_at is null;
